function Seller({user}:{user:User|null}){const [services,setServices]=useState<any[]>([]),[cats,setCats]=useState<Category[]>([]),[categoriesLoading,setCategoriesLoading]=useState(true),[categoriesError,setCategoriesError]=useState(''),[error,setError]=useState('');const load=()=>{api<any>('/seller/services').then(x=>setServices(x.services)).catch(e=>setError(e.message))};useEffect(()=>{void api<unknown>('/categories').then(data=>setCats(parseCategoryResponse(data))).catch(e=>setCategoriesError(e instanceof Error?e.message:'Categories could not be loaded.')).finally(()=>setCategoriesLoading(false));load()},[]);if(!user)return <div className="page"><span className="eyebrow">SELLER WORKSPACE</span><h1>Seller workspace</h1><p>Sign in with a freelancer account to manage your services.</p><Link to="/login" className="button">Sign in</Link> <Link to="/apply-seller">Apply as a freelancer</Link></div>;const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const file=f.get('thumbnail') as File;try{let thumbnailPath=null;if(file?.size){assertUploadSize(file.size);const fd=new FormData();fd.set('file',file);fd.set('kind','service');thumbnailPath=(await api<any>('/media',{method:'POST',body:fd})).path}const d={title:f.get('title'),description:f.get('description'),priceIdr:Number(f.get('priceIdr')),categoryId:f.get('categoryId'),estimatedDays:Number(f.get('estimatedDays')),thumbnailPath,status:f.get('status')};await api('/seller/services',{method:'POST',body:JSON.stringify(d)});(e.target as HTMLFormElement).reset();load()}catch(e:any){setError(e.message)}};return <div className="page"><span className="eyebrow">DASHBOARD</span><h1>My Services</h1>{user.role!=='seller'?<div className="note">Account type: <b>{user.role==='admin'?'Admin':user.role==='seller'?'Freelancer':'Customer'}</b>. Apply for a freelancer role to access this dashboard. <Link to="/apply-seller">Apply now →</Link></div>:<><SellerProfileSettings/><form className="formcard serviceform" onSubmit={save}><h2>Add a service</h2><label>Title (5–100 characters)<input name="title" required minLength={5} maxLength={100}/></label><label>Description<textarea name="description" required maxLength={10000} rows={4}/></label><label>Price in IDR<input name="priceIdr" type="text" inputMode="numeric" pattern="[0-9]+" minLength={5} required/></label><label>Estimated completion (days)<input name="estimatedDays" type="number" min="1" step="1" required/></label><label>Category{categoriesLoading&&<small role="status">Loading categories…</small>}{categoriesError&&<small role="alert">{categoriesError}</small>}{!categoriesLoading&&!categoriesError&&!cats.length&&<small role="status">No categories are currently available.</small>}<select name="categoryId" required disabled={categoriesLoading||!!categoriesError||!cats.length}>{cats.map(c=><option key={c.id} value={c.id}>{categoryDisplayName(c.name)}</option>)}</select></label><label>Thumbnail (PNG/JPG/WebP, max. 12 MB)<input type="file" name="thumbnail" accept="image/png,image/jpeg,image/webp"/></label><label>Status<select name="status"><option value="draft">Draft</option><option value="published">Published</option></select></label><button className="button" disabled={categoriesLoading||!!categoriesError||!cats.length}>Save service</button>{error&&<p className="feedback">{error}</p>}</form><h2>Your services</h2><div className="grid">{services.map(s=><div key={s.id}><ServiceCard service={{...s,seller_name:user.display_name}}/><ServiceEditor service={s} categories={cats} categoriesAvailable={!categoriesLoading&&!categoriesError&&cats.length>0} reload={load}/></div>)}</div></>}</div>}
function Admin(){return <div className="page"><span className="eyebrow">ADMINISTRATION</span><h1>Administration</h1><p className="muted">Review role requests and manage marketplace services.</p><div className="admin-shortcuts"><Link className="admin-shortcut" to="/admin/applications"><b>Role Application</b><span>Review role requests →</span></Link><Link className="admin-shortcut" to="/admin/services"><b>Service Moderation</b><span>Suspend or restore services →</span></Link></div></div>}function AdminApplications(){const [apps,setApps]=useState<AdminRoleApplication[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true);const load=()=>api<unknown>('/admin/applications').then(data=>setApps(parseAdminApplications(data))).catch(e=>setError(e instanceof Error?e.message:'Applications could not be loaded.')).finally(()=>setLoading(false));useEffect(()=>{void load();},[]);const review=async(id:string,decision:'approved'|'rejected')=>{setBusy(true);setError('');try{await api(`/admin/applications/${id}/review`,{method:'POST',body:JSON.stringify({decision})});await load();}catch(e){setError(e instanceof Error?e.message:'Application review failed.');}finally{setBusy(false)}};const pending=[...new Map(apps.filter(a=>a.status==='pending').map(a=>[a.user_id,a])).values()];return <div className="page"><span className="eyebrow">ADMINISTRATION</span><h1>Role Applications</h1><nav className="admin-issue-nav" aria-label="Admin issue sections"><Link className="button outline" to="/admin/issues">Order Issues</Link><Link className="button" aria-current="page" to="/admin/applications">Role Applications</Link></nav>{error&&<div className="alert" role="alert">{error}</div>}{loading&&<p role="status">Loading applications…</p>}{pending.map(a=><article className="order" key={a.id}><div><h3>{a.display_name} · {a.application_type==='admin'?'Admin':'Freelancer'} application</h3><small>{a.email}</small><p>{a.reason}</p>{a.portfolio_url&&<a href={a.portfolio_url} target="_blank" rel="noreferrer">View portfolio →</a>}{a.supporting_file_path&&<p><a href={a.supporting_file_path}>Open private supporting file</a></p>}</div><div className="orderactions"><button className="button small" disabled={busy} onClick={()=>void review(a.id,'approved')}>Approve</button><button className="button outline small" disabled={busy} onClick={()=>void review(a.id,'rejected')}>Reject</button></div></article>)}{!loading&&!pending.length&&!error&&<div className="empty">No role applications are waiting for review.</div>}</div>}function Profile({user,onChange,onLogout}:{user:User|null;onChange:()=>void;onLogout:()=>Promise<void>}){const [name,setName]=useState(user?.display_name||''),[phone,setPhone]=useState(formatPhoneInput(user?.contact_phone||'')),[savedPhone,setSavedPhone]=useState<string|null>(user?.contact_phone??null),[error,setError]=useState(''),[message,setMessage]=useState(''),[saving,setSaving]=useState(false);useEffect(()=>{setName(user?.display_name||'');setPhone(formatPhoneInput(user?.contact_phone||''));setSavedPhone(user?.contact_phone??null)},[user?.display_name,user?.contact_phone]);if(!user)return <div className="page profile-page" lang="en"><span className="eyebrow">ACCOUNT</span><h1>My Profile</h1><p>Sign in to manage your account.</p><Link className="button" to="/login">Sign in</Link></div>;const profileError=(e:unknown)=>{if(!(e instanceof Error))return 'Something went wrong. Please try again.';if(e.message==='VALIDATION')return 'Please check the information and try again.';if(e.message==='INVALID_FILE')return 'Choose a valid PNG, JPG, or WebP image.';if(e.message==='UNAUTHENTICATED')return 'Your session has expired. Please sign in again.';if(e.message==='UPLOAD_LIMIT')return 'Each file must be 12 MB or smaller.';return /^[A-Z][A-Z0-9_]*$/.test(e.message)?'Something went wrong. Please try again.':e.message};const saveName=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setSaving(true);setError('');setMessage('');try{const contactPhone=savedPhone!==null&&phone===formatPhoneInput(savedPhone)||phone.trim()==='+62'?undefined:normalizePhone(phone);await api('/profile',{method:'PUT',body:JSON.stringify({displayName:name,contactPhone})});setSavedPhone(phone);onChange();setMessage('Profile updated successfully.')}catch(e){setError(profileError(e))}finally{setSaving(false)}};const saveAvatar=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const file=new FormData(e.currentTarget).get('avatar') as File;if(!file?.size)return;setSaving(true);setError('');setMessage('');try{assertUploadSize(file.size);const form=new FormData();form.set('file',file);form.set('kind','avatar');await api('/media',{method:'POST',body:form});onChange();setMessage('Profile photo updated successfully.')}catch(e){setError(profileError(e))}finally{setSaving(false)}};const changePassword=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setSaving(true);setError('');setMessage('');const form=e.currentTarget;try{await api('/profile/password',{method:'PUT',body:JSON.stringify(formObject(new FormData(form)))});form.reset();setMessage('Password changed successfully.')}catch(e){setError(profileError(e))}finally{setSaving(false)}};return <div className="page narrow profile-page" lang="en"><span className="eyebrow">ACCOUNT</span><h1>My Profile</h1>{error&&<p className="feedback" role="alert">{error}</p>}{message&&<p className="feedback" role="status">{message}</p>}<section className="profile-email-row"><div className="profile-email-details"><span className="profile-email-label">Registered Email</span><strong>{user.email}</strong></div><button className="logout-button" type="button" onClick={()=>void (async()=>{if(await confirmAction('Are you sure you want to log out?'))await onLogout()})()}>Logout</button></section><div className="profile-sections"><div className="profile-photo-row">{user.avatar_path?<img className="profile-avatar" src={user.avatar_path} alt="Profile photo"/>:<span className="profile-avatar profile-avatar-fallback" aria-hidden="true">{user.display_name.slice(0,1).toUpperCase()}</span>}<form className="formcard profile-form" onSubmit={saveAvatar}><label>Profile photo (PNG/JPG/WebP, max. 12 MB)<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp" required/></label><button className="button outline" disabled={saving}>Save photo</button></form></div><form className="formcard profile-form" onSubmit={saveName}><label>Display name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2} maxLength={80}/></label><label>Phone number<input type="tel" autoComplete="tel" value={phone} onChange={e=>setPhone(formatPhoneInput(e.target.value))} placeholder="+62 812-3456-7890"/></label><button className="button" disabled={saving}>Save profile</button></form><form className="formcard profile-form" onSubmit={changePassword}><h2>Change Password</h2><label>Current password<input name="currentPassword" type="password" autoComplete="current-password" required/></label><label>New password (at least 10 characters)<input name="newPassword" type="password" autoComplete="new-password" required minLength={10} maxLength={72}/></label><button className="button" disabled={saving}>Change password</button></form></div></div>}
export default App;
